#!/usr/bin/env python3
"""Jev decision generated by prompt2jev from classify_request.json.

One System One request sends every question at once; the code below reads the typed
answers. Every threshold lives in the constants block. The defaults are illustrative:
tune them on labeled data before an answer triggers an action.

Run:
    source ~/tools/jev/jev.env              # local gateway :8018, no cloud
    python3 classify_decide.py             # judges EXAMPLE_STATE
    python3 classify_decide.py state.json  # judges the JSON object in that file; - reads stdin
"""

from __future__ import annotations

import json
import os
import sys
import time
import urllib.error
import urllib.request

MODEL = "jev-latest"  # pin a versioned id such as jev-1.13.0 once thresholds are tuned

ENDPOINT = os.environ.get("TYPESAFE_BASE_URL", "http://127.0.0.1:8018").rstrip("/") + "/v1/systemone"

# ----- Constants: every threshold in one place -----
CONFIDENCE_FLOOR = 0.5  # a Choice or Score below this is not acted on; a person decides
NOUL_YES = 0.8  # a Noul at or above this counts as yes
NOUL_NO = 0.2  # a Noul at or below this counts as no; in between is uncertain

QUESTIONS = {
    "semantic_type": {
        "type": "choice",
        "instructions": {
            "question": "What kind of entity is `entity.title` on this wiki?",
            "focus": "Judge the entity itself, not the beings who happen to have used it.",
        },
        "criteria": {
            "technique": "A learned or performed move, attack or skill the being uses.",
            "transformation": "A form the being's body reaches and changes into.",
            "power_up": "A temporary boost that amplifies the being without being a form of its own.",
            "fusion": "A being or state that exists only because two or more beings merged.",
            "trait": "An inherent characteristic, physical property or innate feature, not something performed.",
            "character": "A person or being.",
            "race": "A species, race or clan.",
            "item": "An object or artifact.",
            "location": "A place or world.",
            "organization": "A group, team or institution.",
            "event": "A battle, arc or happening.",
            "media": "An episode, chapter, film, game or other publication.",
            "unknown": "None of the above, or the page does not say enough to tell.",
        },
    },
    "race_exclusive": {
        "type": "noul",
        "instructions": {
            "question": "Can only members of one species, race or clan ever have `entity.title`?",
            "focus": "Judge the entity itself, not the beings who happen to have used it.",
        },
        "criteria": {
            "true": "Only one race can have it. A form that needs a trigger (a full moon, a ritual) is still race-exclusive if only that race responds to the trigger.",
            "false": "Beings of more than one race can have it, or it is not tied to race.",
        },
    },
    "biologically_intrinsic": {
        "type": "noul",
        "instructions": {
            "question": "Does `entity.title` come from what the being is?",
            "focus": "Judge the entity itself, not the beings who happen to have used it.",
        },
        "criteria": {
            "true": "It comes from the being's own nature. Latent potential that another character draws out is still intrinsic: the power was already theirs.",
            "false": "It is learned, given, or comes from outside the being.",
        },
    },
    "externally_granted": {
        "type": "noul",
        "instructions": {
            "question": "Does the power of `entity.title` itself come from a source outside the being?",
            "focus": "Judge the entity itself, not the beings who happen to have used it.",
        },
        "criteria": {
            "true": "It comes from an artifact, a wish, a parasite, a serum, or absorbing another being's energy.",
            "false": "It was already the being's; an outside condition at most triggers something the being already had.",
        },
    },
    "teachable": {
        "type": "noul",
        "instructions": {
            "question": "Can another being learn `entity.title` given training or instruction?",
            "focus": "Judge the entity itself, not the beings who happen to have used it.",
        },
        "criteria": {
            "true": "Others can learn it by training or instruction.",
            "false": "It cannot be taught; it is innate, granted, or unique.",
        },
    },
    "stackable": {
        "type": "noul",
        "instructions": {
            "question": "Can `entity.title` be active at the same time as another form, amplifying it?",
            "focus": "Judge the entity itself, not the beings who happen to have used it.",
        },
        "criteria": {
            "true": "It is active on top of another form and amplifies it.",
            "false": "It replaces the current form, or it is not a form-like state at all.",
        },
    },
    "temporary": {
        "type": "noul",
        "instructions": {
            "question": "Does `entity.title` wear off on its own?",
            "focus": "Judge the entity itself, not the beings who happen to have used it.",
        },
        "criteria": {
            "true": "It ends by itself after a time or once its energy is spent.",
            "false": "It lasts until the being chooses to end it, or it is permanent.",
        },
    },
    "requires_artifact": {
        "type": "noul",
        "instructions": {
            "question": "Does obtaining or keeping `entity.title` need an object?",
            "focus": "Judge the entity itself, not the beings who happen to have used it.",
        },
        "criteria": {
            "true": "An object is needed to obtain it or keep it active.",
            "false": "No object is needed.",
        },
    },
    "requires_fusion": {
        "type": "noul",
        "instructions": {
            "question": "Does `entity.title` exist only because two or more beings merged?",
            "focus": "Judge the entity itself, not the beings who happen to have used it.",
        },
        "criteria": {
            "true": "It exists only through two or more beings merging.",
            "false": "No merging of beings is involved.",
        },
    },
}

# The state the request was written against. Build the real one from your own data.
EXAMPLE_STATE = {
    "entity": {
        "series": "db",
        "title": "Spirit Bomb Super Saiyan",
        "wiki_categories": "Saiyans, Supportive techniques, Techniques, Transformations",
        "wiki_class_field": "Transformation",
        "known_users": "Future Trunks, Goku, Ultra Fusion, Vegeta, Dragon Ball Fusions, Dragon Ball Z: Shin Budokai, Dragon Ball Xenoverse 2",
        "inventor": "(none recorded)",
        "description": "Spirit Bomb Super Saiyan is the result of a Super Saiyan becoming empowered via absorbing a Spirit Bomb.",
    },
}


def ask(state) -> dict:
    """POST the request with the standard library; retry 429 and 529 with backoff, three attempts."""
    key = os.environ.get("TYPESAFE_API_KEY", "local").strip() or "local"
    if not ENDPOINT.startswith(("http://127.0.0.1", "http://localhost")):
        sys.exit(f"Refusing non-local endpoint {ENDPOINT}: this stack is local-only")
    body = json.dumps({"model": MODEL, "state": state, "questions": QUESTIONS}).encode("utf-8")
    for attempt in range(1, 4):
        request = urllib.request.Request(ENDPOINT, data=body, method="POST", headers={
            "Authorization": f"Bearer {key}", "Content-Type": "application/json"})
        try:
            with urllib.request.urlopen(request, timeout=30) as reply:
                return json.load(reply)
        except urllib.error.HTTPError as error:
            if error.code not in (429, 529) or attempt == 3:
                sys.exit(f"TypeSafe returned HTTP {error.code}: {error.read(300).decode('utf-8', 'replace')}")
            retry_after = error.headers.get("retry-after", "")
            time.sleep(float(retry_after) if retry_after.isdigit() else 2 ** (attempt - 1))
        except urllib.error.URLError as error:  # DNS failure, refused connection, TLS problem
            sys.exit(f"Could not reach {ENDPOINT}: {error.reason}")
    raise AssertionError("unreachable")


def read_choice(answer) -> dict:
    """The chosen option, or needs_review when the distribution is too flat to act on."""
    acted = answer["confidence"] >= CONFIDENCE_FLOOR
    return {"choice": answer["choice"] if acted else "needs_review", "confidence": answer["confidence"],
            "probabilities": answer["probabilities"]}


def read_score(answer) -> dict:
    """The probability-weighted level and the nearest level's description."""
    level = int(answer["score"] + 0.5)
    return {"score": answer["score"], "level": level, "label": answer["legend"][str(level)], "confidence": answer["confidence"]}


def read_noul(answer) -> dict:
    """P(yes) with a yes / uncertain / no band. A Noul has no separate confidence."""
    value = answer["noul"]
    band = "yes" if value >= NOUL_YES else "no" if value <= NOUL_NO else "uncertain"
    return {"noul": value, "band": band}


def decide(state) -> dict:
    """Read every answer, then branch. Replace the return with the decision your code needs."""
    response = ask(state)
    answers = response["answers"]
    semantic_type = read_choice(answers["semantic_type"])
    race_exclusive = read_noul(answers["race_exclusive"])
    biologically_intrinsic = read_noul(answers["biologically_intrinsic"])
    externally_granted = read_noul(answers["externally_granted"])
    teachable = read_noul(answers["teachable"])
    stackable = read_noul(answers["stackable"])
    temporary = read_noul(answers["temporary"])
    requires_artifact = read_noul(answers["requires_artifact"])
    requires_fusion = read_noul(answers["requires_fusion"])
    # Branch on the values above here; keep every threshold as a constant at the top.
    return {
        "model": response["model"],
        "semantic_type": semantic_type,
        "race_exclusive": race_exclusive,
        "biologically_intrinsic": biologically_intrinsic,
        "externally_granted": externally_granted,
        "teachable": teachable,
        "stackable": stackable,
        "temporary": temporary,
        "requires_artifact": requires_artifact,
        "requires_fusion": requires_fusion,
    }


def main(argv: list[str]) -> int:
    if len(argv) > 1:
        with (sys.stdin if argv[1] == "-" else open(argv[1], encoding="utf-8")) as handle:
            state = json.load(handle)
    else:
        state = EXAMPLE_STATE
    print(json.dumps(decide(state), ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
